# Patch Starlette's default multipart form field size limit to 50MB
# to allow for large base64 strings generated by FLUX models.
import starlette.formparsers  # pyre-ignore[21]
try:
    starlette.formparsers.MAX_FORM_FIELD_SIZE = 50 * 1024 * 1024 # pyre-ignore
except Exception:
    pass


sys.path.append(os.path.dirname(os.path.abspath(__file__)))

from ai_services import FaceIdentifier, DigitalSurgeon, BiometricEncoder, CriminalDatabase  # pyre-ignore[21]

app = FastAPI(title="F.A.C.E.S. Refinement API")

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

@app.exception_handler(RequestValidationError)
async def validation_exception_handler(request: Request, exc: RequestValidationError):
    body = await request.body()
    print(f"Validation Error 422/400. Body preview: {str(body)[:100]}...")  # pyre-ignore[16]
    print(f"Details: {exc.errors()}")
    return JSONResponse(status_code=400, content={"detail": exc.errors()})

@app.exception_handler(Exception)
async def global_exception_handler(request: Request, exc: Exception):
    print(f"Global Exception caught: {exc}")
    import traceback
    traceback.print_exc()
    return JSONResponse(status_code=500, content={"detail": str(exc)})

print("Initializing Surgical Refinement Architecture...")
