class RefinementResponse(BaseModel):
    image: str
    message: str
    debug_mask: str | None = None

@app.get("/")
def read_root():
    return {"status": "online", "service": "F.A.C.E.S. Surgical Refinement API"}


@app.post("/api/generate-composite")
async def generate_composite(prompt: str = Form(...), seed: int = Form(0)):
    """
    Generate an initial forensic composite sketch from a text description.
    Uses Stable Diffusion via the DigitalSurgeon.
    """
    try:
        if surgeon is None:
            raise HTTPException(status_code=503, detail="Surgical unit unavailable")
            
        print(f"[Generate] Requesting initial composite from Stable Diffusion...")
        
        try:
            result_image = surgeon.generate(prompt=prompt, seed=seed)  # pyre-ignore[16]
        except RuntimeError as re:
            print(f"[Generate] AI Service error: {re}")
            raise HTTPException(status_code=502, detail=str(re))
        except Exception as ge:
            print(f"[Generate] Generation error: {ge}")
            raise HTTPException(status_code=502, detail=f"Image generation failed: {str(ge)}")
        
        if result_image is None:
            raise HTTPException(status_code=502, detail="Image generation service returned empty result. Please check API keys or service logs.")

        # Convert to base64 for frontend consumption
        buffered = io.BytesIO()
        result_image.save(buffered, format="PNG")
        img_b64 = base64.b64encode(buffered.getvalue()).decode("utf-8")
        
        print("[Generate] Composite generation complete!")
        return {"image": f"data:image/png;base64,{img_b64}"}
            
    except HTTPException:
        raise
    except Exception as e:
        print(f"[Generate] Unexpected error: {e}")
        import traceback
        traceback.print_exc()
        raise HTTPException(status_code=500, detail=str(e))



# The "Nose Dictionary" - precise prompts for surgical refinement
NOSE_PROMPTS = {
    "button": "Short, small, upturned button nose with round tip",
    "hooked": "Prominent aquiline nose, hooked shape, dorsal hump, downward tip",
    "aquiline": "Prominent aquiline nose, hooked shape, dorsal hump, downward tip",
    "wide": "Broad, flat nose, wide nostrils, low nose bridge",
    "broad": "Broad, flat nose, wide nostrils, low nose bridge",
    "straight": "Perfectly straight, narrow nose bridge, symmetrical",
    "snub": "Small, short snub nose, slightly upturned",
    "hawk": "Sharp, angular hawk-like nose",
    "pointed": "Sharp, pointed nose with defined structure"
}

@app.post("/api/refine-feature", response_model=RefinementResponse)
async def refine_feature(
    image: str = Form(...),
    feature_name: str = Form(...),
    refinement_prompt: str = Form(...),
    updated_prompt: str = Form(""),
    seed: int = Form(0)
):
    try:
        if identifier is None or surgeon is None:
             raise HTTPException(status_code=503, detail="AI Services unavailable")

        print(f"Received surgical request: {feature_name} -> {refinement_prompt} (Seed: {seed})")
        
        # 1. Decode Image
        try:
            if "base64," in image:
                image_data = base64.b64decode(image.split("base64,")[1])
            else:
                image_data = base64.b64decode(image)
                
            original_image = Image.open(io.BytesIO(image_data)).convert("RGB")
        except Exception as e:
            raise HTTPException(status_code=400, detail=f"Invalid image data: {str(e)}")

        # 2. Step 1: The "Identifier" (Masking)
        print(f"Step 1: Identifying target area for '{feature_name}'...")
        # Use simple fallback strategy which now includes the 'Nose Box' logic
        mask = identifier.get_mask(original_image, feature_name, strategy="auto")  # pyre-ignore[16]
        
        # 3. Post-Process Mask with surgical boundary enforcement
        processed_mask = identifier.process_mask(mask, feature_name=feature_name)  # pyre-ignore[16]

        # 4. Step 2: The "Surgeon" (Inpainting)
        print(f"Step 2: Performing refinement...")
        
        lower_prompt = refinement_prompt.lower()
        feature_lower = feature_name.lower()
        
        # --- LOGIC BRANCHES ---
        
        # We use the full contextual prompt correctly passed from the frontend
        full_prompt = updated_prompt if updated_prompt else refinement_prompt
        
        # Branch A: Surgical Nose Job
        if "nose" in feature_lower:
            print(">>> ACTIVATING SURGICAL NOSE JOB PIPELINE <<<")
            
            # Check if user selected one of our preset styles
            nose_desc = refinement_prompt
            for style, style_prompt in NOSE_PROMPTS.items():
                if style in lower_prompt or style in feature_lower:
                    nose_desc = style_prompt
                    break
            
            actual_prompt = f"forensic sketch pencil drawing of a human nose, specifically {nose_desc}, black and white line art, detailed pencil shading, clean contours, technical illustration style"
            negative_prompt = "color, realistic photo, blur, double nose, deformed, extra nostrils, rough sketch, heavy shading, 3d render"
            strength_val = 0.90
            guidance_scale_val = 7.5
            steps_val = 20
            mask_blur_val = 3
            model_type_val = "cloudflare"

        # Branch B: Removal (Beards, glasses, etc.)
        elif any(k in lower_prompt for k in ["remove", "without", "no ", "delete", "gone", "clean-shaven", "bare face"]):
            print(f"Detected REMOVAL intent for: {feature_name}")
            actual_prompt = f"smooth clean skin texture, bare skin, clean face, detailed forensic sketch, black and white pencil shading"
            negative_prompt = f"beard, mustache, moustache, stubble, facial hair, {feature_name}, distortion, unnatural, color"
            strength_val = 0.85
            guidance_scale_val = 7.5
            steps_val = 20
            mask_blur_val = 3
            model_type_val = "cloudflare"
            
        # Branch C: Hair
        elif feature_lower in ["hair", "hairstyle", "hairStyle"] or "hair" in lower_prompt:
            print(f"Detected HAIRSTYLE modification")
            actual_prompt = f"forensic sketch pencil drawing of hairstyle: {refinement_prompt}, black and white only, detailed pencil strokes"
            negative_prompt = "deformed, blurry, color, realistic photo, low quality"
            strength_val = 0.90
            guidance_scale_val = 7.5
            steps_val = 20
            mask_blur_val = 3
            model_type_val = "cloudflare"
            
        # Branch D: Surgical Eye Refinement
        elif any(k in feature_lower for k in ["eye", "eyes", "eyeball", "eyelid"]):
            print(f">>> ACTIVATING SURGICAL EYES PIPELINE <<<")
            actual_prompt = f"forensic sketch pencil drawing of human eyes, specifically {refinement_prompt}, black and white line art, detailed pencil shading, clean contours, symmetrical realistic pupils and irises"
            negative_prompt = "color, realistic photo, blur, deformed, extra eyes, double iris, 3d render, distorted"
            strength_val = 0.85
            guidance_scale_val = 7.5
            steps_val = 20
            mask_blur_val = 3
            model_type_val = "cloudflare"

        # Branch E: Surgical Lips / Mouth Refinement
        elif any(k in feature_lower for k in ["lip", "lips", "mouth", "smile"]):
            print(f">>> ACTIVATING SURGICAL LIPS PIPELINE <<<")
            actual_prompt = f"forensic sketch pencil drawing of human lips and mouth, specifically {refinement_prompt}, black and white line art, detailed pencil shading, clean contours, natural lip texture"
            negative_prompt = "color, realistic photo, blur, deformed lips, extra teeth, distortion, 3d render"
            strength_val = 0.85
            guidance_scale_val = 7.5
            steps_val = 20
            mask_blur_val = 3
            model_type_val = "cloudflare"

        # Branch F: Perceived Age / Skin Aging Refinement
        elif "age" in feature_lower or any(k in lower_prompt for k in ["years old", "age", "older", "younger", "wrinkle", "elderly", "youthful"]):
            print(f">>> ACTIVATING SURGICAL AGE REFINEMENT PIPELINE <<<")
            import re
            age_match = re.search(r'\b(\d{1,2})\b', lower_prompt)
            target_age = int(age_match.group(1)) if age_match else None

            if target_age and target_age >= 55:
                age_detail = f"elderly mature adult, {target_age} years old, prominent forehead wrinkles, deep crow's feet wrinkles around eyes, nasolabial laugh lines, mature aging skin texture"
                neg_detail = "smooth youthful skin, child, teenager, baby"
            elif target_age and target_age >= 40:
                age_detail = f"middle-aged adult, {target_age} years old, subtle forehead lines, light crow's feet, mature skin texture"
                neg_detail = "smooth youthful skin, child, teenager, deep sagging wrinkles"
            elif target_age and target_age <= 30:
                age_detail = f"youthful young adult, {target_age} years old, smooth youthful unwrinkled skin, firm skin texture, clear complexion, fresh youthful features"
                neg_detail = "wrinkles, deep creases, sagging skin, old, elderly, age spots"
            else:
                age_detail = f"adult face, natural skin texture, {refinement_prompt}"
                neg_detail = "distortion, blur, unnatural skin"

            actual_prompt = (
                f"forensic sketch pencil drawing of human face, specifically {age_detail}, "
                f"black and white line art, detailed pencil shading, clean contours, "
                f"maintaining same facial identity and features"
            )
            negative_prompt = f"color, realistic photo, 3d render, blur, deformed, distorted, {neg_detail}"
            strength_val = 0.70
            guidance_scale_val = 7.5
            steps_val = 20
            mask_blur_val = 3
            model_type_val = "cloudflare"

        # Branch G: General Refinement (jaw, chin, cheekbones, etc.)
        else:
            print(f"Standard surgical refinement pipeline for {feature_name}")
            actual_prompt = f"forensic sketch pencil drawing of {feature_name}, {refinement_prompt}, black and white only, detailed pencil line art"
            negative_prompt = "color, realistic photo, 3d render, blur, low quality, distortion, artifacts"
            strength_val = 0.85
            guidance_scale_val = 7.5
            steps_val = 20
            mask_blur_val = 3
            model_type_val = "cloudflare"

        try:
            result_image = surgeon.inpaint(  # pyre-ignore[16]
                image=original_image,
                mask=processed_mask,
                prompt=actual_prompt,
                negative_prompt=negative_prompt,
                strength=strength_val,
                guidance_scale=guidance_scale_val,
                num_inference_steps=steps_val,
                mask_blur=mask_blur_val,
                model_type=model_type_val,
                seed=seed
            )
        except RuntimeError as re:
            print(f"[Refine] AI Service error: {re}")
            raise HTTPException(status_code=502, detail=str(re))
        except Exception as ge:
            print(f"[Refine] Refinement error: {ge}")
            raise HTTPException(status_code=502, detail=f"Refinement failed: {str(ge)}")

        if result_image is None:
            raise HTTPException(status_code=502, detail="Refinement service returned empty result.")

        # 5. Encode Response
        buffered = io.BytesIO()
        result_image.save(buffered, format="PNG")  # pyre-ignore[16]
        img_str = base64.b64encode(buffered.getvalue()).decode("utf-8")
        
        # Encode Mask for Debugging
        mask_buffered = io.BytesIO()
        processed_mask.save(mask_buffered, format="PNG")
        mask_str = base64.b64encode(mask_buffered.getvalue()).decode("utf-8")
        
        return {
            "image": f"data:image/png;base64,{img_str}",
            "message": f"Successfully refined {feature_name}",
            "debug_mask": f"data:image/png;base64,{mask_str}"
        }

    except Exception as e:
        print(f"Refinement Error: {e}")
        import traceback
        traceback.print_exc()
        raise HTTPException(status_code=500, detail=f"Internal processing error: {str(e)}")

@app.post("/api/search-database")
async def search_database(image: str = Form(...)):
    try:
        if encoder is None or db is None:
             raise HTTPException(status_code=503, detail="Search service unavailable")

        try:
            if "base64," in image:
                image_data = base64.b64decode(image.split("base64,")[1])
            else:
                image_data = base64.b64decode(image)
            original_image = Image.open(io.BytesIO(image_data)).convert("RGB")
        except Exception as e:
            raise HTTPException(status_code=400, detail="Invalid image data")

        vector = encoder.encode(original_image)  # pyre-ignore[16]
        print(f"Generated vector for search. Querying database...")
        
        matches = db.search(vector, top_n=6)  # pyre-ignore[16]
        
        return {
            "matches": matches
        }
            
    except Exception as e:
        print(f"Search Error: {e}")
        import traceback
        traceback.print_exc()
        raise HTTPException(status_code=500, detail=f"Search failed: {str(e)}")

@app.post("/api/tts")
async def text_to_speech(text: str = Form(...)):
    print(f"TTS Request: {text}")
    try:
        ELEVENLABS_API_KEY = os.getenv("ELEVENLABS_API_KEY")
        if not ELEVENLABS_API_KEY:
             print("Warning: ELEVENLABS_API_KEY not set. Returning silently to avoid errors.")
             return {"audio": ""}

        url = "https://api.elevenlabs.io/v1/text-to-speech/nPczCjzI2devNBz1zQrb" # Declan ID (or similar deep voice)
        
        headers = {
            "Accept": "audio/mpeg",
            "Content-Type": "application/json",
            "xi-api-key": ELEVENLABS_API_KEY  # pyre-ignore[6]
        }
        
        data = {
            "text": text,
            "model_id": "eleven_multilingual_v2",
            "voice_settings": {
                "stability": 0.5,
                "similarity_boost": 0.75
            }
        }

        import requests  # pyre-ignore[21]
        response = requests.post(url, json=data, headers=headers)
        
        if response.status_code != 200:
            print(f"ElevenLabs Error: {response.text}")
            raise HTTPException(status_code=response.status_code, detail="TTS generation failed")

        # Encode audio to base64 to send back JSON (or stream binary)
        # For simplicity with current setup, let's return base64
        audio_base64 = base64.b64encode(response.content).decode('utf-8')
        
        return {"audio": f"data:audio/mpeg;base64,{audio_base64}"}

    except Exception as e:
        print(f"TTS Error: {e}")
        raise HTTPException(status_code=500, detail=str(e))

